    let reranker = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        tokio::task::block_in_place(|| RerankEngine::load_with_device(&config.inference.device))
    })) {
        Ok(Ok(r)) => { info!("Reranker BGE listo"); Some(Arc::new(r)) }
        Ok(Err(e)) => { warn!("Reranker no disponible (fallback a RRF puro): {}", e); None }
        Err(_) => { warn!("Reranker: ort panico al cargar (ONNX Runtime ausente o incompatible) -- fallback a RRF puro"); None }
    };
